using System.Windows;using OdinVault.Manager.Wpf.Services;namespace OdinVault.Manager.Wpf.Views;public partial class UpdateView:System.Windows.Controls.UserControl{readonly GitHubUpdateService updater=new();UpdateCheckResult? update;public UpdateView(){InitializeComponent();VersionText.Text=$"نسخه فعلی: {updater.GetCurrentVersion()}";Unloaded+=(_,_)=>updater.Dispose();}async void Check_Click(object s,RoutedEventArgs e){CheckButton.IsEnabled=false;try{StatusText.Text="در حال بررسی GitHub…";update=await updater.CheckAsync();StatusText.Text=update.IsUpdateAvailable?$"نسخه {update.LatestVersion} آماده است.":$"نسخه {update.CurrentVersion} آخرین نسخه است.";InstallButton.IsEnabled=update.IsUpdateAvailable;}catch(Exception ex){StatusText.Text=$"خطا: {ex.Message}";}finally{CheckButton.IsEnabled=true;}}async void Install_Click(object s,RoutedEventArgs e){if(update is null||!update.IsUpdateAvailable)return;if(System.Windows.MessageBox.Show("نسخه جدید دانلود، SHA256 آن بررسی و سپس Installer با دسترسی Administrator اجرا شود؟","تأیید بروزرسانی",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;InstallButton.IsEnabled=false;Progress.Visibility=Visibility.Visible;try{var p=new Progress<UpdateDownloadProgress>(x=>Progress.Value=x.Percent);var path=await updater.DownloadInstallerAsync(update,p);StatusText.Text="اعتبار فایل تأیید شد؛ Installer در حال اجراست…";GitHubUpdateService.LaunchInstaller(path);System.Windows.Application.Current.Shutdown();}catch(Exception ex){StatusText.Text=$"خطا: {ex.Message}";InstallButton.IsEnabled=true;}}}